window.docContents[185].resolve({"/#Functional-Programming-in-Lean--Monads--Example___-Arithmetic-in-Monads--Further-Effects--Exercises--Readers-with-Failure":{"contents":"Adapt the reader monad example so that it can also indicate failure when the custom operator is not defined, rather than just returning zero.\nIn other words, given these definitions:\n\n\n\ndo the following:\n\n1. Write suitable pure and bind functions2. Check that these functions satisfy the  contract3. Write  instances for  and 4. Define suitable  operators and test them with  on some example expressions\n\n","context":"Functional Programming in Lean\u0009Monads\u0009Example: Arithmetic in Monads\u0009Further Effects\u0009Exercises","header":"4.3.3.4.2. Readers with Failure","id":"/#Functional-Programming-in-Lean--Monads--Example___-Arithmetic-in-Monads--Further-Effects--Exercises--Readers-with-Failure"}});